; UI module: King Kai / Luka telepathy window, Dragon Radar, scouter, Goku's
; STATUS page text, dialogue window placement and R fast-forward.
;   code  !CODE_UI ($AC:8000-FFFF, ROM 0x2C8000), data in the same half bank
;         (the lower halves of $EC-$EF hold ending art)
;   data  generated by snes/gen/ui.mjs into dist/snes/gen/ui/
;   WRAM  !RAM_UI ($7E:7E40, $C0 bytes; cleared by core at every title entry)
;   SRAM  !SRAM_WORK_UI ($33:7C00, $400 bytes staging), !PERSIST_UI (request)
; See docs/agents/snes-port/ui.md for the hardware approach and the API.

incsrc "ui/defines.asm"

; ---------------------------------------------------------------------------
; Integration points. Define these before this file to connect providers
; from other modules; with the story module (included first) they bind to
; its API, otherwise to local stubs fed by the UI test client.
if defined("STORY_LAYOUT")
	!UI_HAVE_STORY = 1
	if not(defined("UI_NAME_FN"))
		!UI_NAME_FN = story_api_display_name
	endif
	if not(defined("UI_QUEST_STATUS_FN"))
		!UI_QUEST_STATUS_FN = story_api_quest_status
	endif
	if not(defined("UI_RADAR_STATE_FN"))
		!UI_RADAR_STATE_FN = ui_story_radar_state
	endif
endif
if not(defined("UI_NAME_FN"))
	!UI_NAME_FN = ui_default_name     ; A16 = n (0-3) -> X16 = name in bank $7E (0-terminated)
endif
if not(defined("UI_QUEST_STATUS_FN"))
	!UI_QUEST_STATUS_FN = ui_stub_quest_status ; -> A16 = held | collected<<8, X16 = wished
endif
; The story module calls this hook when a Ball is collected (A = palace).
; (STORY_TEST builds bind every hook to the story's own logger first.)
if not(defined("STORY_HOOK_QUEST_COLLECTED"))
	!STORY_HOOK_QUEST_COLLECTED = ui_hook_quest_collected
endif

; ---------------------------------------------------------------------------
; WRAM (!RAM_UI, $C0 bytes). Absolute with DB = $7E: LDA.w !x&$FFFF.
!ui_state     = !RAM_UI+$00   ; word: !UIS_* bits
!ui_phase     = !RAM_UI+$02   ; word: window renderer phase (!UIP_*)
!ui_cur       = !RAM_UI+$04   ; word: current message id + 1 (0 none)
!ui_left      = !RAM_UI+$06   ; word: frames the current message stays up
!ui_cur_par   = !RAM_UI+$08   ; word: its parameter (lo number, hi string index)
!ui_cur_map   = !RAM_UI+$0A   ; word: map + 1 a barrier message belongs to (0 any)
!ui_qn        = !RAM_UI+$0C   ; word: queued messages (queue in SRAM, !ui_s_queue)
!ui_held      = !RAM_UI+$0E   ; word: visible frames at full Super Saiyan power this charge
!ui_warned    = !RAM_UI+$10   ; word: per-charge warning latch
!ui_cool      = !RAM_UI+$12   ; word: warning cooldown
!ui_bcool     = !RAM_UI+$14   ; word: barrier remark cooldown (8 s)
!ui_rcool     = !RAM_UI+$16   ; word: roof remark cooldown
!ui_lastmap   = !RAM_UI+$18   ; word: map + 1 seen last frame (0 none)
!ui_charge_in = !RAM_UI+$1A   ; word: ui_charge_tick input ($8000 | !UIC_*), consumed per frame
!ui_block     = !RAM_UI+$1C   ; word: hide requests from other modules (bit per owner)
!ui_drawn     = !RAM_UI+$1E   ; word: message id + 1 on screen (0 none)
!ui_in        = !RAM_UI+$20   ; word: inputs from other modules (!UII_*)
!ui_vis       = !RAM_UI+$22   ; word: radio visible this frame (0/1)
!ui_place     = !RAM_UI+$24   ; word: first BG3 row of the drawn box (1 or 17)
!ui_tmp0      = !RAM_UI+$26   ; word scratch (main thread)
!ui_tmp1      = !RAM_UI+$28
!ui_tmp2      = !RAM_UI+$2A
!ui_tmp3      = !RAM_UI+$2C
!ui_tmp4      = !RAM_UI+$2E
!ui_tmp5      = !RAM_UI+$30
!ui_ptr       = !RAM_UI+$32   ; 3 bytes: long pointer (used as [dp] with D = !RAM_UI&$FF00)
!ui_frame     = !RAM_UI+$36   ; word: UI frames (any mode)
!ui_test      = !RAM_UI+$38   ; word: test mailbox command (UI_TEST builds)
!ui_test_a    = !RAM_UI+$3A   ; word: test argument A
!ui_test_x    = !RAM_UI+$3C   ; word: test argument X
!ui_drawn_par = !RAM_UI+$3E   ; word: parameter of the drawn message
!ui_stub_q    = !RAM_UI+$40   ; word: stub quest status (held | collected<<8) without story
!ui_charge_seen = !RAM_UI+$42 ; word: this frame's charge input ($8000 | !UIC_*, 0 none)
!ui_qend      = !RAM_UI+$44   ; word: queue scratch (ui_q_remove)
!ui_row_want  = !RAM_UI+$46   ; word: BG3 row of the box for the current message
!ui_test_charge = !RAM_UI+$48 ; word: UI_TEST builds: ui_charge_tick flags every frame
!ui_bidx      = !RAM_UI+$4A   ; word: barrier index being judged
; world flight band and radar (world.asm)
!ui_band      = !RAM_UI+$4C   ; word: 0 off, 1 content queued, 2 shown (IRQs armed)
!ui_wirq      = !RAM_UI+$4E   ; byte: IRQ chain state (0 horizon, 1 band start, 2 band end)
!ui_band_key  = !RAM_UI+$50   ; word: content on the band (radio id+1, or $8000 | radar key)
!ui_band_par  = !RAM_UI+$52   ; word: radio parameter drawn
!ui_watlas    = !RAM_UI+$54   ; word: world atlas upload: 0 none, 1 first half, 2 done
!ui_claims    = !RAM_UI+$56   ; word: bit0 region B, bit1 region C claimed
!ui_sweep_ph  = !RAM_UI+$58   ; word: sweep phase (65536 = one turn)
!ui_sweep_up  = !RAM_UI+$5A   ; word: sweep angle prepared + 1 (0 none)
!ui_blip_x    = !RAM_UI+$5C   ; word: blip centre in dial pixels
!ui_blip_y    = !RAM_UI+$5E
!ui_rguide    = !RAM_UI+$60   ; word: guide (0 land, 1 ahead, 2 around, 3 left, 4 right)
!ui_rtarget   = !RAM_UI+$62   ; word: target (0-6 palace, 7 tree, 8 frieza, 9 dryad, 10 finale)
!ui_rdist     = !RAM_UI+$64   ; word: distance in world pixels
!ui_dial_up   = !RAM_UI+$66   ; word: dial upload steps done (!UI_DIAL_UPS = all tiles in VRAM)
!ui_radar_on  = !RAM_UI+$68   ; word: radar shown this frame
!ui_rflags    = !RAM_UI+$6A   ; word: radar state flags (!UIR_*) this frame
!ui_rmask     = !RAM_UI+$6C   ; word: held | collected << 8 this frame
!ui_rtx       = !RAM_UI+$6E   ; word: target x
!ui_rty       = !RAM_UI+$70   ; word: target y
!ui_k0        = !RAM_UI+$72   ; word: dial / bearing scratch (world frame)
!ui_stub_rf   = !RAM_UI+$74   ; word: stub radar flags without the providers
!ui_k1        = !RAM_UI+$76   ; words: more world-frame scratch
!ui_k2        = !RAM_UI+$78
!ui_k3        = !RAM_UI+$7A
!ui_k4        = !RAM_UI+$7C
!ui_k5        = !RAM_UI+$7E
!ui_k6        = !RAM_UI+$80
!ui_magic     = !RAM_UI+$82   ; word: !UI_MAGIC once this cartridge set the block up
!UI_MAGIC     = $4B41         ; (savestates from other builds carry stale WRAM here)
!ui_band_was  = !RAM_UI+$84   ; word: BG3 registers redirected (restore when the band goes)
!ui_front_n   = !RAM_UI+$86   ; word: native sprites moved behind the dial this frame
!ui_bx8       = !RAM_UI+$88   ; word: radar target across the heading (1/8 px)
!ui_by8       = !RAM_UI+$8A   ; word: along the heading (1/8 px)
!ui_m0        = !RAM_UI+$8C   ; word: 32-bit scratch (low)
!ui_m1        = !RAM_UI+$8E   ; word: 32-bit scratch (high)
!ui_ma        = !RAM_UI+$90   ; word: multiply scratch
!ui_mb        = !RAM_UI+$92
!ui_msign     = !RAM_UI+$94
!ui_rdx       = !RAM_UI+$96   ; word: radar target delta x (world wrap)
!ui_rdy       = !RAM_UI+$98   ; word: delta y
!ui_rtimer    = !RAM_UI+$9A   ; word: frames until the radar target is selected again
!ui_rvalid    = !RAM_UI+$9C   ; word: a radar target exists
!ui_rlast_h   = !RAM_UI+$9E   ; word: heading of the last far-blip computation
!ui_rfar      = !RAM_UI+$A0   ; word: geometry passes until the far blip is recomputed
!ui_blink     = !RAM_UI+$A2   ; word: blip blink phase (0-29)
!ui_rphase    = !RAM_UI+$A4   ; word: bearing halves done since the radar showed (bit0 rotated, bit1 geometry)
; +$A6-$A9: fast-forward (ff.asm)
; +$AA-$AD: window placement (place.asm)
; +$AE-$AF: scouter (scouter.asm)
; +$B0-$B7: free

!ui_name_buf  = !RAM_UI+$B8   ; 8 bytes: display name buffer ({n} codes)

!UI_QMAX = 16

; !ui_state bits
!UIS_DRAWN = $0001            ; the box is on BG3 (tilemap uploaded)
!UIS_ATLAS = $0002            ; glyph atlas resident in BG3 tiles $122-$1C1
!UIS_HDMA  = $0004            ; palette HDMA (channel 5) armed
!UIS_INIT  = $0008            ; WRAM initialised since the last title entry

; build steps (!ui_s_bstep): one per frame, so a new message or radar text
; never costs a frame more than one step
!UIB_TEXT  = $0001            ; expand the text (all lines) and the static rows
!UIB_TEXT0 = $0002            ; radar: text line 1 only (the guide changed)
!UIB_LINE0 = $0004            ; map rows of text line 1
!UIB_LINE1 = $0008            ; ... line 2
!UIB_LINE2 = $0010            ; ... line 3
!UIB_ALL   = !UIB_TEXT|!UIB_LINE0|!UIB_LINE1|!UIB_LINE2

; window renderer phases
!UIP_IDLE   = 0
!UIP_ATLASB = 1               ; atlas first half queued, second half next

; ui_charge_tick flags (A16)
!UIC_SUPER = $0001            ; charging in Super Saiyan form
!UIC_FULL  = $0002            ; at full power (browser: charge >= 45)
!UIC_BEAM  = $0004            ; a beam action is running (asides wait)

; !ui_in bits: other modules' state the radio follows
!UII_CRISIS        = $0001    ; the five-minute core crisis is active
!UII_FORTRESS_GONE = $0002    ; the Fortress was destroyed (drop flight advice)
!UII_ACTION_BEAM   = $0004    ; a beam action is running (asides wait)
!UII_WORLD_YIELD   = $0008    ; world flight: docking, an aerial ki shot or explosion (the radar hides)

; ---------------------------------------------------------------------------
; Persistent fields (battery SRAM, copied into each GAME FILE's sidecar).
; Requested range: !PERSIST_MISC+$80..+$DF (see ui.md "Core requests").
if not(defined("PERSIST_UI"))
	!PERSIST_UI = !PERSIST_MISC+$80
endif
!ui_p_flags    = !PERSIST_UI+$00 ; byte: !UIF_* bits
!ui_p_warning  = !PERSIST_UI+$01 ; byte: next King Kai warning (rotation)
!ui_p_attempts = !PERSIST_UI+$02 ; word: sustained Super Saiyan charges judged
!ui_p_roll     = !PERSIST_UI+$04 ; dword: xorshift32 state (0 = unset, seed $6D2B79F5)
!ui_p_bcount   = !PERSIST_UI+$08 ; byte: barrier remark rotation counter
!ui_p_rremarks = !PERSIST_UI+$09 ; byte: ceiling remarks used
!ui_p_rexits   = !PERSIST_UI+$0A ; word: ceiling exits
!ui_p_rlast    = !PERSIST_UI+$0C ; word: exit count at the last remark
!ui_p_barriers = !PERSIST_UI+$10 ; 8 bytes: barrier reaction keys used (bit = barrier index)
!ui_p_roofs    = !PERSIST_UI+$20 ; 64 bytes: maps with a ceiling exit (bit = map 0-511)
!PERSIST_UI_SIZE = $60

!UIF_FIRST_FLIGHT = $01       ; first-flight banter given (browser firstFlight)
!UIF_INTRO_FLIGHT = $02       ; power intro: first hover
!UIF_INTRO_SUPER  = $04       ; power intro: first transformation
!UIF_JOKE_GOLD    = $08       ; scouter jokes told
!UIF_JOKE_FRIEZA  = $10
!UIF_JOKE_GOKU    = $20

; SRAM staging (!SRAM_WORK_UI, $400 bytes; contents undefined at boot)
!ui_s_map   = !SRAM_WORK_UI+$000   ; $200: the window's 8 BG3 rows (32 words each)
!ui_s_hdma  = !SRAM_WORK_UI+$200   ; $40: palette HDMA table (channel 5, mode 3 -> $2121)
!ui_s_text  = !SRAM_WORK_UI+$240   ; 168 bytes: 3 x 28 glyph words ((code - $80) * 2) of the message
!ui_s_trig  = !SRAM_WORK_UI+$2E8   ; 10 bytes: heading + 1, sin, cos, |sin|, |cos| (radar cache)
                                   ; $2F2-$2F3 free
!ui_s_bkey  = !SRAM_WORK_UI+$2F4   ; word: content staged in !ui_s_map/!ui_s_text (id+1, or $8000|radar key)
!ui_s_bpar  = !SRAM_WORK_UI+$2F6   ; word: its parameter
!ui_s_bmode = !SRAM_WORK_UI+$2F8   ; word: 1 field window, 2 world band, 0 nothing staged
!ui_s_bstep = !SRAM_WORK_UI+$2FA   ; word: build steps still to do (!UIB_*)
!ui_s_rkey  = !SRAM_WORK_UI+$2FC   ; word: radar text key without the guide (set with the target)
!ui_s_rin   = !SRAM_WORK_UI+$2FE   ; 10 bytes: heading, x, y, target x, y of the last rotation
!ui_s_gin   = !SRAM_WORK_UI+$308   ; 10 bytes: the same for the distance/guide/blip on screen
                                   ; $312-$33E: window placement tables (place.asm)
!ui_s_queue = !SRAM_WORK_UI+$340   ; !UI_QMAX x 8 bytes: id+1, param, map+1, frames left
!ui_s_wband = !SRAM_WORK_UI+$3C0   ; 28 bytes: world band colours (HDMA ch6 data: 09 09 lo hi ...)
!ui_s_wsky  = !SRAM_WORK_UI+$3DC   ; 28 bytes: the sky's colours 9-15 in the same layout
!ui_front   = !SRAM_WORK_UI+$200   ; 8 x 8 bytes (world only; the field's HDMA table otherwise):
                                   ; native sprites moved behind the dial (slot, x/y, tile)

; BG3 layout (field, Mode 1): chr $4000, tilemap $5800 (32x32).
!UI_BG3_CHR    = $4000
!UI_BG3_MAP    = $5800
!UI_ROW_TOP    = 1            ; native window rows 1-8 (lines 8-71)
!UI_ROW_LOWER  = 17           ; rows 17-24 (lines 136-199), just above the HUD
!UI_KB_DROP    = $01          ; kind bits (ui_kind_bits)
!UI_KB_ASIDE   = $02
!UI_KB_BOTTOM  = $04

; ui_hide owner bit of the endings: also keeps native windows in place
!UI_HIDE_ENDING = $4000

pushpc
org !CODE_UI
ui_code_start:
incsrc "main.asm"
incsrc "radio.asm"
incsrc "window.asm"
incsrc "world.asm"
incsrc "ff.asm"
incsrc "place.asm"
incsrc "scouter.asm"
if defined("UI_TEST")
	incsrc "../../../test/ui/testmod.asm"
endif
ui_data_start:
incsrc "ui/messages.asm"
incsrc "ui/radar.asm"
ui_atlas:
	incbin "ui/atlas.bin"
ui_atlas_end:
ui_window_tiles:
	incbin "ui/window.bin"
ui_zero_rows:
	fillbyte $00 : fill $200
ui_watlas_data:
	incbin "ui/watlas.bin"
ui_dial_data:
	incbin "ui/dial.bin"
ui_code_end:
assert ui_code_end <= !CODE_UI+$8000, "ui bank overflow"
pullpc

; World IRQ entry (00:8A4B SEP #$20 / PHA / PHB / LDA #$00): the band IRQs.
%orig4($C08A4B, $8B4820E2)
%orig2($C08A4F, $00A9)
%hijack($C08A4B, ui_world_irq, 6, ui)
